from pathlib import Path
p=Path('/mnt/data/star_navigator_v06/app.js')
s=p.read_text()
# Replace state
s=s.replace("let guidedState={destId:null,step:0};", "let currentLocationId='cabin7456';\nlet guidedState={destId:null,step:0};\n\nconst locations=[\n  {id:'cabin7456',name:'Cabin 7456',deck:'7',area:'Forward / center',icon:'🏠',mapDeck:'7',mapNode:null,keywords:'cabin 7456 home'},\n  ...destinations.map(d=>({id:d.id,name:d.name,deck:String(d.mapDeck),area:d.area,icon:d.icon,mapDeck:String(d.mapDeck),mapNode:d.mapNode,keywords:d.keywords}))\n];\nfunction locationById(id){return locations.find(x=>x.id===id)||locations[0]}\nfunction routeFor(fromId,toId){\n  const from=locationById(fromId); const to=destinations.find(x=>x.id===toId); if(!to)return [];\n  if(from.id==='cabin7456') return to.route;\n  const sameDeck=String(from.mapDeck)===String(to.mapDeck);\n  const areaForward=/Forward/i.test(to.area);\n  const areaAft=/Aft/i.test(to.area);\n  const homeLike=from.name.toLowerCase().includes('cabin');\n  const departText=homeLike\n    ? `Start at ${from.name} and use the cabin corridor toward the most useful elevator/stair connection shown on the deck map.`\n    : `Start at ${from.name}. Use the nearby ship landmarks and signs to reach the next navigation point.`;\n  if(sameDeck){\n    return [\n      {kind:'walk',text:departText},\n      {kind:'orient',text:`Stay on Deck ${from.mapDeck} and orient ${areaForward?'forward':areaAft?'aft':'toward the destination area'} toward ${to.name}.`},\n      {kind:'arrive',text:`Follow signs and nearby landmarks to ${to.name}.`}\n    ];\n  }\n  return [\n    {kind:'walk',text:departText},\n    {kind:'elevator',text:`Take the appropriate elevator or stair connection from Deck ${from.mapDeck} to Deck ${to.mapDeck}.`},\n    {kind:'orient',text:`On Deck ${to.mapDeck}, orient ${areaForward?'forward':areaAft?'aft':'toward the destination area'} toward ${to.name}.`},\n    {kind:'arrive',text:`Follow signs and nearby landmarks to ${to.name}.`}\n  ];\n}\nfunction routeAreaLabel(fromId,to){const from=locationById(fromId);return `${from.name} → ${to.name}`;}" )
# guidedMapFor use current location/deck
old="""function guidedMapFor(d,idx){\n  const step=d.route[idx]||d.route[0];\n  if(step.kind==='walk') return `<div class=\"guided-map-label\">DECK 7 · CABIN 7456</div>${shipMapSVG('7',null,'route')}`;\n  if(step.kind==='elevator') return `<div class=\"deck-change-card\"><div class=\"deck-change-icon\">🛗</div><div class=\"deck-from\">DECK 7</div><div class=\"deck-arrow\">↓</div><div class=\"deck-to\">DECK ${esc(d.mapDeck)}</div><small>Use ship signage to confirm the deck before exiting.</small></div>`;\n  return `<div class=\"guided-map-label\">DECK ${esc(d.mapDeck)} · ${esc(d.name)}</div>${shipMapSVG(d.mapDeck,d.mapNode,'route')}`;\n}\n"""
new="""function guidedMapFor(d,idx){\n  const step=d.route[idx]||d.route[0];\n  const from=locationById(currentLocationId);\n  if(step.kind==='walk') return `<div class=\"guided-map-label\">DECK ${esc(from.mapDeck)} · ${esc(from.name)}</div>${shipMapSVG(from.mapDeck,from.mapNode,'route')}`;\n  if(step.kind==='elevator'){\n    const fromDeck=String(from.mapDeck), toDeck=String(d.mapDeck);\n    const direction=Number(toDeck.match(/\\d+/)?.[0]||0)>=Number(fromDeck.match(/\\d+/)?.[0]||0)?'↑':'↓';\n    return `<div class=\"deck-change-card\"><div class=\"deck-change-icon\">🛗</div><div class=\"deck-from\">DECK ${esc(fromDeck)}</div><div class=\"deck-arrow\">${direction}</div><div class=\"deck-to\">DECK ${esc(toDeck)}</div><small>Use ship signage to confirm the deck before exiting.</small></div>`;\n  }\n  return `<div class=\"guided-map-label\">DECK ${esc(d.mapDeck)} · ${esc(d.name)}</div>${shipMapSVG(d.mapDeck,d.mapNode,'route')}`;\n}\n"""
s=s.replace(old,new)
# Replace renderGuidedRoute entirely via split
start=s.index('function renderGuidedRoute(){')
end=s.index('function showRecovery', start)
new_render="""function renderGuidedRoute(){\n  const d=destinations.find(x=>x.id===guidedState.destId);if(!d)return;\n  d.route=routeFor(currentLocationId,d.id);\n  const idx=Math.max(0,Math.min(guidedState.step,d.route.length-1)); const s=d.route[idx];\n  const type=s.kind==='elevator'?'DECK CHANGE':s.kind==='arrive'?'ARRIVE':s.kind==='orient'?'ORIENT':'WALK';\n  const pct=Math.round(((idx+1)/d.route.length)*100);\n  const from=locationById(currentLocationId);\n  const nearby=d.id==='aquadome'||d.id==='torque'?`<div class=\"nearby-card\"><div class=\"confidence\">WHILE YOU'RE HERE</div><h3>Nearby in AquaDome</h3><div class=\"nearby-chips\"><span>💎 The Overlook</span><span>☕ Rye & Bean</span><span>🍴 AquaDome Market</span></div></div>`:d.id==='basecamp'?`<div class=\"nearby-card\"><div class=\"confidence\">WHILE YOU'RE HERE</div><h3>Nearby in Thrill Island</h3><div class=\"nearby-chips\"><span>🧗 Adrenaline Peak</span><span>⛳ Lost Dunes</span><span>🏄 FlowRider</span></div></div>`:'';\n  const progressText=`STEP ${idx+1} OF ${d.route.length}`;\n  el('routeContent').innerHTML=`<div class=\"location-picker\"><button class=\"location-field\" id=\"fromLocationBtn\"><span>📍 FROM</span><strong>${esc(from.name)}</strong><small>Deck ${esc(from.mapDeck)} · change</small></button><div class=\"location-arrow\">→</div><button class=\"location-field\" id=\"toLocationBtn\"><span>🎯 TO</span><strong>${esc(d.name)}</strong><small>Deck ${esc(d.mapDeck)}</small></button></div><div class=\"guided-top\"><button class=\"back-btn\" onclick=\"navigate('home')\">‹ Exit</button><div class=\"guided-progress\"><span>${progressText}</span><div><i style=\"width:${pct}%\"></i></div></div></div><div class=\"route-hero guided-hero\"><div class=\"eyebrow\">${esc(routeAreaLabel(currentLocationId,d))}</div><h2>${type}</h2><div class=\"route-tag\">Deck ${idx<2?esc(from.mapDeck):esc(d.mapDeck)} · ${esc(d.area)}</div></div><div class=\"guided-map\">${guidedMapFor(d,idx)}<button class=\"map-open guided-full\" data-openmap=\"${d.id}\">Expand map</button></div><div class=\"instruction-card\"><div class=\"step-num big\">${idx+1}</div><div><div class=\"step-type\">${type}</div><div class=\"instruction-text\">${esc(s.text)}</div></div></div>${idx===d.route.length-1?nearby:''}<div class=\"guided-actions\">${idx>0?'<button class=\"secondary-action\" id=\"prevGuide\">← Previous</button>':''}<button class=\"confused-action\" id=\"confusedBtn\">? I\'m confused</button>${idx<d.route.length-1?'<button class=\"next-action\" id=\"nextGuide\">NEXT →</button>':'<button class=\"next-action\" id=\"finishGuide\">✓ ARRIVED</button>'}</div>`;\n  el('fromLocationBtn').onclick=()=>openLocationPicker('from');\n  el('toLocationBtn').onclick=()=>openLocationPicker('to');\n  if(el('nextGuide'))el('nextGuide').onclick=()=>{guidedState.step++;renderGuidedRoute()};\n  if(el('prevGuide'))el('prevGuide').onclick=()=>{guidedState.step--;renderGuidedRoute()};\n  if(el('finishGuide'))el('finishGuide').onclick=()=>navigate('home');\n  if(el('confusedBtn'))el('confusedBtn').onclick=()=>showRecovery(d,idx);\n}\nfunction openLocationPicker(mode){\n  const current=mode==='from'?currentLocationId:guidedState.destId;\n  el('overlayTitle').textContent=mode==='from'?'Where are you starting?':'Where do you want to go?';\n  const list=locations.filter(x=>mode==='from'||x.id!=='cabin7456');\n  el('overlayMap').innerHTML=`<div class=\"location-picker-sheet\"><p>${mode==='from'?'Choose your current location. Route will recalculate immediately.':'Choose a new destination while keeping your current location.'}</p><input id=\"locationSearch\" class=\"location-search\" placeholder=\"Search locations...\" autocomplete=\"off\"><div id=\"locationChoices\">${renderLocationChoices(list,current)}</div><div class=\"recovery-tip\"><strong>Tip:</strong> you can change this again at any time during the route.</div></div>`;\n  el('mapOverlay').classList.add('show');el('mapOverlay').setAttribute('aria-hidden','false');\n  const search=el('locationSearch');\n  search.oninput=()=>{const q=search.value.toLowerCase().trim();const filtered=list.filter(x=>(x.name+' '+x.area+' '+x.keywords).toLowerCase().includes(q));el('locationChoices').innerHTML=renderLocationChoices(filtered,current)};\n  el('locationChoices').querySelectorAll('[data-location-choice]').forEach(b=>b.onclick=()=>{\n    const id=b.dataset.locationChoice;\n    closeMap();\n    if(mode==='from'){currentLocationId=id;guidedState.step=0;} else {guidedState.destId=id;currentLocationId=currentLocationId;}\n    const d=destinations.find(x=>x.id===guidedState.destId);\n    if(d){document.body.classList.toggle('route-aft',/Aft/i.test(d.area));renderGuidedRoute();}\n  });\n}\nfunction renderLocationChoices(list,current){return list.map(x=>`<button class=\"location-choice ${x.id===current?'selected':''}\" data-location-choice=\"${x.id}\"><span>${x.icon||'📍'}</span><span><strong>${esc(x.name)}</strong><small>Deck ${esc(x.mapDeck)} · ${esc(x.area)}</small></span>${x.id===current?'<b>✓</b>':''}</button>`).join('')||'<div class=\"empty-choice\">No matching locations.</div>'}\n"""
s=s[:start]+new_render+s[end:]
# showRoute reset current? should retain current location, use from state.
s=s.replace("function showRoute(id){\n  const d=destinations.find(x=>x.id===id);if(!d)return; currentMapState=d.id; guidedState={destId:id,step:0};", "function showRoute(id){\n  const d=destinations.find(x=>x.id===id);if(!d)return; currentMapState=d.id; guidedState={destId:id,step:0};")
# takeHome: make it a destination route rather than static home screen; need current = existing, target cabin special. Replace handler block.
oldstart=s.index("el('takeHome').addEventListener('click'", s.index('function showMustDo'))
oldend=s.index("el('infoBtn').onclick", oldstart)
newhome="""el('takeHome').addEventListener('click',()=>{\n  if(currentLocationId==='cabin7456'){\n    el('routeContent').innerHTML=`<div class=\"route-hero\"><div class=\"eyebrow\">HOME BASE</div><h2>Already Home</h2><div class=\"route-tag\">Cabin 7456 · Deck 7</div></div><div class=\"map-card\">${shipMapSVG('7',null,'route')}<div class=\"map-disclaimer\">You are currently set to Cabin 7456.</div></div><button class=\"home-action\" onclick=\"navigate('home')\">⌂ Back to Navigator</button>`;navigate('route');return;\n  }\n  const homeDest={id:'cabin7456',name:'Cabin 7456',area:'Forward / center',mapDeck:'7',mapNode:null,deck:'7',route:routeFor(currentLocationId,'centralpark')};\n  currentLocationId=currentLocationId;\n  const from=locationById(currentLocationId);\n  const steps=from.mapDeck==='7'?[{kind:'walk',text:`From ${from.name}, stay on Deck 7 and use cabin-number signage toward Cabin 7456.`},{kind:'arrive',text:'Use the cabin-number signs to find Cabin 7456.'}]:[{kind:'walk',text:`From ${from.name}, use the nearest elevator or stair connection.`},{kind:'elevator',text:`Travel from Deck ${from.mapDeck} to Deck 7.`},{kind:'orient',text:'On Deck 7, orient toward the forward / center cabin corridor.'},{kind:'arrive',text:'Use cabin-number signage to find Cabin 7456.'}];\n  guidedState={destId:'__home__',step:0};\n  window.__homeRoute={...homeDest,route:steps};\n  const original=destinations.find(x=>x.id==='guestservices');\n  const faux={...homeDest};\n  faux.route=steps;\n  // Render a home-directed route using the same guided UI.\n  const idx=0; const pct=Math.round(100/steps.length); const s=steps[0];\n  const type=s.kind==='elevator'?'DECK CHANGE':s.kind==='arrive'?'ARRIVE':s.kind==='orient'?'ORIENT':'WALK';\n  el('routeContent').innerHTML=`<div class=\"location-picker\"><button class=\"location-field\" id=\"fromLocationBtn\"><span>📍 FROM</span><strong>${esc(from.name)}</strong><small>Deck ${esc(from.mapDeck)} · change</small></button><div class=\"location-arrow\">→</div><button class=\"location-field\"><span>🎯 TO</span><strong>Cabin 7456</strong><small>Deck 7</small></button></div><div class=\"guided-top\"><button class=\"back-btn\" onclick=\"navigate('home')\">‹ Exit</button><div class=\"guided-progress\"><span>STEP 1 OF ${steps.length}</span><div><i style=\"width:${pct}%\"></i></div></div></div><div class=\"route-hero guided-hero\"><div class=\"eyebrow\">${esc(from.name)} → CABIN 7456</div><h2>${type}</h2><div class=\"route-tag\">Deck ${esc(from.mapDeck)} · Home</div></div><div class=\"guided-map\"><div class=\"guided-map-label\">DECK ${esc(from.mapDeck)}</div>${shipMapSVG(from.mapDeck,from.mapNode,'route')}</div><div class=\"instruction-card\"><div class=\"step-num big\">1</div><div><div class=\"step-type\">${type}</div><div class=\"instruction-text\">${esc(s.text)}</div></div></div><div class=\"guided-actions\"><button class=\"confused-action\" id=\"confusedBtnHome\">? I\'m confused</button>${steps.length>1?'<button class=\"next-action\" id=\"nextHome\">NEXT →</button>':'<button class=\"next-action\" onclick=\"navigate(\'home\')\">✓ ARRIVED</button>'}</div>`;\n  el('fromLocationBtn').onclick=()=>openLocationPicker('from');\n  if(el('nextHome'))el('nextHome').onclick=()=>renderHomeGuideStep(1);\n  if(el('confusedBtnHome'))el('confusedBtnHome').onclick=()=>{el('overlayTitle').textContent='Where are you now?';el('overlayMap').innerHTML=`<div class=\"recovery\"><p>Pick a landmark you recognize to re-orient.</p>${locations.filter(x=>x.id!=='cabin7456').slice(0,12).map(x=>`<button class=\"recovery-place\" data-homerecover=\"${x.id}\">📍 ${esc(x.name)}</button>`).join('')}</div>`;el('mapOverlay').classList.add('show');el('mapOverlay').setAttribute('aria-hidden','false');el('overlayMap').querySelectorAll('[data-homerecover]').forEach(b=>b.onclick=()=>{currentLocationId=b.dataset.homerecover;closeMap();el('takeHome').click()})};\n  navigate('route');\n});\nfunction renderHomeGuideStep(idx){\n  const r=window.__homeRoute;if(!r)return; const from=locationById(currentLocationId); const step=r.route[idx]; if(!step)return;\n  el('routeContent').innerHTML=`<div class=\"location-picker\"><button class=\"location-field\" id=\"fromLocationBtn\"><span>📍 FROM</span><strong>${esc(from.name)}</strong><small>Deck ${esc(from.mapDeck)} · change</small></button><div class=\"location-arrow\">→</div><button class=\"location-field\"><span>🎯 TO</span><strong>Cabin 7456</strong><small>Deck 7</small></button></div><div class=\"guided-top\"><button class=\"back-btn\" onclick=\"navigate('home')\">‹ Exit</button><div class=\"guided-progress\"><span>STEP ${idx+1} OF ${r.route.length}</span><div><i style=\"width:${Math.round(((idx+1)/r.route.length)*100)}%\"></i></div></div></div><div class=\"route-hero guided-hero\"><div class=\"eyebrow\">${esc(from.name)} → CABIN 7456</div><h2>${step.kind==='elevator'?'DECK CHANGE':step.kind==='arrive'?'ARRIVE':step.kind==='orient'?'ORIENT':'WALK'}</h2></div><div class=\"guided-map\">${step.kind==='elevator'?`<div class=\"deck-change-card\"><div class=\"deck-change-icon\">🛗</div><div class=\"deck-from\">DECK ${esc(from.mapDeck)}</div><div class=\"deck-arrow\">↓</div><div class=\"deck-to\">DECK 7</div></div>`:shipMapSVG(step.kind==='arrive'?'7':from.mapDeck,null,'route')}</div><div class=\"instruction-card\"><div class=\"step-num big\">${idx+1}</div><div><div class=\"instruction-text\">${esc(step.text)}</div></div></div><div class=\"guided-actions\">${idx>0?'<button class=\"secondary-action\" id=\"prevHome\">← Previous</button>':''}${idx<r.route.length-1?'<button class=\"next-action\" id=\"nextHome\">NEXT →</button>':'<button class=\"next-action\" onclick=\"navigate(\'home\')\">✓ ARRIVED</button>'}</div>`;\n  el('fromLocationBtn').onclick=()=>openLocationPicker('from');\n  if(el('nextHome'))el('nextHome').onclick=()=>renderHomeGuideStep(idx+1);\n  if(el('prevHome'))el('prevHome').onclick=()=>renderHomeGuideStep(idx-1);\n}\n"""
s=s[:oldstart]+newhome+s[oldend:]
p.write_text(s)

# Update HTML version/title
hp=Path('/mnt/data/star_navigator_v06/index.html')
h=hp.read_text().replace('Star Navigator <span>v0.5</span>','Star Navigator <span>v0.6</span>').replace('v0.3 adds visual mini-maps for routes, with Cabin 7456 as your home base.','v0.6 combines visual mini-maps, guided routes, and flexible From/To location control.')
hp.write_text(h)
